leviathan_prime.source:
export const envelope = [64, 52, 64];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const SEAT_Y = 8;

  // Block ID Constants
  const AIR = 0;
  const DARK_PRISMARINE = 1;
  const PRISMARINE_BRICKS = 2;
  const PRISMARINE = 3;
  const CRYING_OBSIDIAN = 4;
  const SEA_LANTERN = 5;
  const BONE_BLOCK = 6;
  const SCULK = 7;
  const QUARTZ_BLOCK = 8;
  const QUARTZ_PILLAR = 9;
  const DEEPSLATE_BRICKS = 10;
  const FROGLIGHT = 11;
  const POINTED_DRIPSTONE = 12;
  const QUARTZ_STAIRS = 13;
  const PRISMARINE_WALL = 14;
  const END_ROD = 15;
  const WARPED_WART = 16;
  const CRACKED_STONE_BRICKS = 17;
  const STONE_BRICKS = 18;
  const QUARTZ_SLAB = 19;

  // 3D Voxel Grid Flattened Buffer
  const totalCells = W * H * D;
  const grid = new Uint8Array(totalCells);

  function getIdx(x, y, z) {
    return x + y * W + z * W * H;
  }

  function setVoxel(x, y, z, val) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[getIdx(x, y, z)] = val;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[getIdx(x, y, z)];
    }
    return AIR;
  }

  // Catmull-Rom Spline Interpolator
  function catmullRom(p0, p1, p2, p3, t) {
    const t2 = t * t;
    const t3 = t2 * t;
    return [
      0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
      0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3),
      0.5 * ((2 * p1[2]) + (-p0[2] + p2[2]) * t + (2 * p0[2] - 5 * p1[2] + 4 * p2[2] - p3[2]) * t2 + (-p0[2] + 3 * p1[2] - 3 * p2[2] + p3[2]) * t3)
    ];
  }

  // Rasterize Swept Tentacle Spline
  function drawTentacle(pts, rStart, rEnd, hasSuctionCups, hasSpines) {
    const steps = 70;
    const numSegments = pts.length - 1;
    const totalSteps = steps * numSegments;

    for (let s = 0; s < numSegments; s++) {
      const p0 = pts[Math.max(0, s - 1)];
      const p1 = pts[s];
      const p2 = pts[s + 1];
      const p3 = pts[Math.min(pts.length - 1, s + 2)];

      for (let step = 0; step < steps; step++) {
        const u = step / steps;
        const globalT = (s * steps + step) / totalSteps;
        const pos = catmullRom(p0, p1, p2, p3, u);
        const radius = rStart + (rEnd - rStart) * globalT;

        const uNext = Math.min(1, u + 0.04);
        const posNext = catmullRom(p0, p1, p2, p3, uNext);
        const uPrev = Math.max(0, u - 0.04);
        const posPrev = catmullRom(p0, p1, p2, p3, uPrev);

        // Curvature Vector for inner vs outer surface orientation
        const kx = posNext[0] - 2 * pos[0] + posPrev[0];
        const ky = posNext[1] - 2 * pos[1] + posPrev[1];
        const kz = posNext[2] - 2 * pos[2] + posPrev[2];
        const kLen = Math.hypot(kx, ky, kz) || 1;
        const inNorm = [kx / kLen, ky / kLen, kz / kLen];

        const rCeil = Math.ceil(radius);
        const cx = Math.round(pos[0]);
        const cy = Math.round(pos[1]);
        const cz = Math.round(pos[2]);

        for (let dx = -rCeil; dx <= rCeil; dx++) {
          for (let dy = -rCeil; dy <= rCeil; dy++) {
            for (let dz = -rCeil; dz <= rCeil; dz++) {
              const d = Math.hypot(dx, dy, dz);
              if (d <= radius) {
                const gx = cx + dx;
                const gy = cy + dy;
                const gz = cz + dz;
                if (gx >= 0 && gx < W && gy >= 0 && gy < H && gz >= 0 && gz < D) {
                  let mat = DARK_PRISMARINE;
                  const dotIn = (dx * inNorm[0] + dy * inNorm[1] + dz * inNorm[2]) / (d || 1);

                  if (d > radius - 1.2) {
                    if (dotIn > 0.25) {
                      mat = PRISMARINE_BRICKS;
                    } else {
                      mat = (gx + gy + gz) % 3 === 0 ? PRISMARINE : DARK_PRISMARINE;
                    }
                  } else if (d < radius - 2.2) {
                    mat = (gx * gz) % 5 === 0 ? CRYING_OBSIDIAN : DARK_PRISMARINE;
                  }

                  setVoxel(gx, gy, gz, mat);
                }
              }
            }
          }
        }

        // Suction cups along inner curve
        if (hasSuctionCups && (step % 10 === 0) && radius >= 1.4 && globalT < 0.9) {
          const scX = pos[0] + inNorm[0] * (radius - 0.2);
          const scY = pos[1] + inNorm[1] * (radius - 0.2);
          const scZ = pos[2] + inNorm[2] * (radius - 0.2);

          for (let sx = -1; sx <= 1; sx++) {
            for (let sy = -1; sy <= 1; sy++) {
              for (let sz = -1; sz <= 1; sz++) {
                const sd = Math.hypot(sx, sy, sz);
                const vx = Math.round(scX + sx);
                const vy = Math.round(scY + sy);
                const vz = Math.round(scZ + sz);
                if (vx >= 0 && vx < W && vy >= 0 && vy < H && vz >= 0 && vz < D) {
                  if (sd < 0.8) {
                    setVoxel(vx, vy, vz, SEA_LANTERN);
                  } else if (sd <= 1.5) {
                    setVoxel(vx, vy, vz, BONE_BLOCK);
                  }
                }
              }
            }
          }
        }

        // Dorsal spines along outer curve
        if (hasSpines && (step % 7 === 0) && radius >= 1.5 && globalT > 0.08 && globalT < 0.92) {
          const outNorm = [-inNorm[0], -inNorm[1], -inNorm[2]];
          const spineLen = Math.min(4, Math.round(radius * 0.75) + 1);
          for (let sl = 0; sl <= spineLen; sl++) {
            const spX = Math.round(pos[0] + outNorm[0] * (radius + sl * 0.75));
            const spY = Math.round(pos[1] + outNorm[1] * (radius + sl * 0.75));
            const spZ = Math.round(pos[2] + outNorm[2] * (radius + sl * 0.75));
            if (spX >= 0 && spX < W && spY >= 0 && spY < H && spZ >= 0 && spZ < D) {
              setVoxel(spX, spY, spZ, sl === spineLen ? PRISMARINE_WALL : BONE_BLOCK);
            }
          }
        }
      }
    }
  }

  // 1. Hellenist Seawall & Promenade (Z = 0 to 8)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z <= 8; z++) {
      const inBreach = (x >= 20 && x <= 44 && z >= 4);
      const deepBreach = (x >= 24 && x <= 40 && z >= 2);

      if (deepBreach) {
        // Monster breach crater
        if ((x + z) % 3 === 0) {
          setVoxel(x, 7, z, DEEPSLATE_BRICKS);
          setVoxel(x, 8, z, (x * z) % 2 === 0 ? CRACKED_STONE_BRICKS : CRYING_OBSIDIAN);
        }
        if ((x + z) % 4 === 0) {
          setVoxel(x, 9, z, (x % 2 === 0) ? QUARTZ_BLOCK : SCULK);
        }
        continue;
      }

      if (inBreach) {
        // Fractured breakwater foundation
        for (let y = 0; y <= 9; y++) {
          setVoxel(x, y, z, DEEPSLATE_BRICKS);
        }
        // Fractured pavement
        if ((x + z) % 4 !== 0) {
          setVoxel(x, 10, z, (x + z) % 2 === 0 ? CRACKED_STONE_BRICKS : STONE_BRICKS);
        } else {
          setVoxel(x, 10, z, CRYING_OBSIDIAN);
        }
        continue;
      }

      // Solid Breakwater Foundation
      for (let y = 0; y <= 9; y++) {
        const mat = (y >= 8 && (x + y + z) % 7 === 0) ? CRACKED_STONE_BRICKS : DEEPSLATE_BRICKS;
        setVoxel(x, y, z, mat);
      }

      // Promenade Deck at Y = 10
      if (z === 1 || z === 7) {
        setVoxel(x, 10, z, QUARTZ_BLOCK);
      } else {
        setVoxel(x, 10, z, (x + z) % 8 === 0 ? CRACKED_STONE_BRICKS : STONE_BRICKS);
      }

      // Parapet at Z = 8
      if (z === 8) {
        if (x < 18 || x > 46) {
          setVoxel(x, 11, z, QUARTZ_BLOCK);
          if (x % 2 === 0) {
            setVoxel(x, 12, z, QUARTZ_SLAB);
          }
        }
      }
    }
  }

  // Neoclassical Columns at Z = 4
  const colX = [6, 12, 18, 46, 52, 58];
  for (let i = 0; i < colX.length; i++) {
    const cx = colX[i];
    if (cx === 6 || cx === 58) {
      // Intact Classical Columns
      setVoxel(cx, 11, 4, QUARTZ_BLOCK);
      setVoxel(cx - 1, 11, 4, QUARTZ_BLOCK);
      setVoxel(cx + 1, 11, 4, QUARTZ_BLOCK);
      for (let y = 12; y <= 18; y++) {
        setVoxel(cx, y, 4, QUARTZ_PILLAR);
      }
      setVoxel(cx, 19, 4, QUARTZ_BLOCK);
      setVoxel(cx - 1, 19, 4, QUARTZ_BLOCK);
      setVoxel(cx + 1, 19, 4, QUARTZ_BLOCK);
      setVoxel(cx, 20, 4, QUARTZ_SLAB);
    } else if (cx === 12 || cx === 52) {
      // Broken Columns
      setVoxel(cx, 11, 4, QUARTZ_BLOCK);
      for (let y = 12; y <= 15; y++) {
        setVoxel(cx, y, 4, QUARTZ_PILLAR);
      }
      setVoxel(cx + (cx === 12 ? 1 : -1), 11, 3, QUARTZ_PILLAR);
      setVoxel(cx + (cx === 12 ? 2 : -2), 11, 2, QUARTZ_BLOCK);
    } else if (cx === 18 || cx === 46) {
      // Columns Wrapped and Crushed by Tentacles
      setVoxel(cx, 11, 4, QUARTZ_BLOCK);
      setVoxel(cx, 12, 4, QUARTZ_PILLAR);
      setVoxel(cx, 13, 4, QUARTZ_PILLAR);
      setVoxel(cx + (cx === 18 ? -1 : 1), 11, 5, QUARTZ_BLOCK);
    }
  }

  // 2. Leviathan Central Torso & Mass
  const bodyDiscs = [
    { pos: [32, 6, 46], rx: 11.5, ry: 9.0, rz: 8.5 },
    { pos: [32, 11, 40], rx: 12.0, ry: 10.0, rz: 8.5 },
    { pos: [32, 17, 33], rx: 12.0, ry: 11.0, rz: 8.5 },
    { pos: [32, 23, 26], rx: 11.0, ry: 10.0, rz: 8.0 },
    { pos: [32, 25, 19], rx: 9.5, ry: 8.5, rz: 7.0 },
    { pos: [32, 25, 14], rx: 7.5, ry: 7.0, rz: 5.5 }
  ];

  for (let i = 0; i < bodyDiscs.length; i++) {
    const bp = bodyDiscs[i];
    const cx = bp.pos[0];
    const cy = bp.pos[1];
    const cz = bp.pos[2];
    const rx = bp.rx;
    const ry = bp.ry;
    const rz = bp.rz;

    for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
      for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
        for (let z = Math.floor(cz - rz); z <= Math.ceil(cz + rz); z++) {
          if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
            const dx = (x - cx) / rx;
            const dy = (y - cy) / ry;
            const dz = (z - cz) / rz;
            const distSq = dx * dx + dy * dy + dz * dz;
            if (distSq <= 1.0) {
              let mat = DARK_PRISMARINE;
              if (distSq > 0.7) {
                if (y < cy - 2) {
                  mat = CRYING_OBSIDIAN;
                } else if ((x + y + z) % 4 === 0) {
                  mat = PRISMARINE_BRICKS;
                } else if ((x * z) % 7 === 0) {
                  mat = SCULK;
                }
              }
              setVoxel(x, y, z, mat);
            }
          }
        }
      }
    }
  }

  // 3. Maw Cavity & Glowing Gullet (Facing -Z)
  for (let z = 12; z <= 23; z++) {
    const t = (z - 12) / (23 - 12);
    const mawRx = 5.8 * (1 - 0.58 * t);
    const mawRy = 4.8 * (1 - 0.58 * t);
    const mcx = 32;
    const mcy = 24;

    for (let x = Math.floor(mcx - mawRx - 1); x <= Math.ceil(mcx + mawRx + 1); x++) {
      for (let y = Math.floor(mcy - mawRy - 1); y <= Math.ceil(mcy + mawRy + 1); y++) {
        if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
          const dx = (x - mcx) / mawRx;
          const dy = (y - mcy) / mawRy;
          const dSq = dx * dx + dy * dy;
          if (dSq <= 1.0) {
            if (z >= 21) {
              setVoxel(x, y, z, (x + y) % 2 === 0 ? SEA_LANTERN : CRYING_OBSIDIAN);
            } else {
              setVoxel(x, y, z, AIR);
            }
          } else if (dSq <= 1.35 && z <= 17) {
            if ((Math.abs(x - mcx) + Math.abs(y - mcy) + z) % 3 === 0) {
              setVoxel(x, y, z, BONE_BLOCK);
            }
          }
        }
      }
    }
  }

  // 4. Dorsal Spines along the Backbone
  for (let z = 18; z <= 46; z += 2) {
    const t = (z - 18) / (46 - 18);
    const spineHeight = Math.round(3 + 5 * Math.sin(t * Math.PI));
    let topY = 0;
    for (let y = H - 1; y >= 10; y--) {
      if (getVoxel(32, y, z) !== AIR) {
        topY = y;
        break;
      }
    }
    if (topY > 0) {
      for (let h = 1; h <= spineHeight; h++) {
        const sy = topY + h;
        if (sy < H) {
          setVoxel(32, sy, z, h === spineHeight ? PRISMARINE_WALL : BONE_BLOCK);
          if (h <= spineHeight - 2) {
            setVoxel(31, sy, z, DARK_PRISMARINE);
            setVoxel(33, sy, z, DARK_PRISMARINE);
          }
        }
      }
    }
  }

  // 5. Eldritch Eyes
  // Left Compound Eye
  setVoxel(25, 27, 16, SEA_LANTERN);
  setVoxel(25, 28, 16, SEA_LANTERN);
  setVoxel(26, 27, 16, SEA_LANTERN);
  setVoxel(26, 28, 16, FROGLIGHT);
  setVoxel(24, 27, 16, CRYING_OBSIDIAN);
  setVoxel(24, 28, 16, CRYING_OBSIDIAN);
  setVoxel(25, 29, 16, CRYING_OBSIDIAN);
  setVoxel(26, 29, 16, CRYING_OBSIDIAN);
  setVoxel(25, 26, 16, CRYING_OBSIDIAN);
  setVoxel(26, 26, 16, CRYING_OBSIDIAN);

  // Right Compound Eye
  setVoxel(38, 27, 16, SEA_LANTERN);
  setVoxel(38, 28, 16, SEA_LANTERN);
  setVoxel(37, 27, 16, FROGLIGHT);
  setVoxel(37, 28, 16, SEA_LANTERN);
  setVoxel(39, 27, 16, CRYING_OBSIDIAN);
  setVoxel(39, 28, 16, CRYING_OBSIDIAN);
  setVoxel(38, 29, 16, CRYING_OBSIDIAN);
  setVoxel(37, 29, 16, CRYING_OBSIDIAN);
  setVoxel(38, 26, 16, CRYING_OBSIDIAN);
  setVoxel(37, 26, 16, CRYING_OBSIDIAN);

  // Forehead Great Eye
  setVoxel(32, 33, 17, FROGLIGHT);
  setVoxel(31, 33, 17, SEA_LANTERN);
  setVoxel(33, 33, 17, SEA_LANTERN);
  setVoxel(32, 34, 17, BONE_BLOCK);
  setVoxel(32, 35, 17, PRISMARINE_WALL);
  setVoxel(30, 33, 17, SCULK);
  setVoxel(34, 33, 17, SCULK);

  // 6. Mandible Fangs
  const fangs = [
    [[26, 28, 15], [24, 30, 12], [24, 27, 9], [27, 25, 7]],
    [[38, 28, 15], [40, 30, 12], [40, 27, 9], [37, 25, 7]],
    [[26, 20, 15], [23, 17, 12], [24, 19, 9], [27, 21, 7]],
    [[38, 20, 15], [41, 17, 12], [40, 19, 9], [37, 21, 7]]
  ];
  for (let i = 0; i < fangs.length; i++) {
    drawTentacle(fangs[i], 1.8, 0.4, false, false);
  }

  // 7. Colossal Spiked Tentacles (8 Appendages)
  const tentacles = [
    // 1: Left Front Crusher (Arches high, smashes down onto seawall)
    {
      pts: [[24, 12, 30], [14, 22, 24], [8, 36, 18], [8, 44, 10], [10, 32, 4], [12, 14, 3], [14, 11, 5]],
      rStart: 4.5, rEnd: 1.8, suctionCups: true, spines: true
    },
    // 2: Right Front Crusher (Looming strike)
    {
      pts: [[40, 12, 30], [50, 24, 24], [56, 38, 18], [55, 47, 12], [50, 36, 6], [46, 22, 2], [44, 11, 3]],
      rStart: 4.5, rEnd: 1.8, suctionCups: true, spines: true
    },
    // 3: Left Central Sky-Piercer (Arching high above maw)
    {
      pts: [[28, 18, 26], [22, 30, 20], [18, 42, 14], [24, 50, 8], [28, 44, 4]],
      rStart: 3.8, rEnd: 1.2, suctionCups: true, spines: true
    },
    // 4: Right Central Sky-Piercer (Arching high above maw)
    {
      pts: [[36, 18, 26], [42, 32, 20], [46, 44, 14], [40, 51, 8], [34, 45, 3]],
      rStart: 3.8, rEnd: 1.2, suctionCups: true, spines: true
    },
    // 5: Left Low Grasper (Wrapping column at X=18)
    {
      pts: [[26, 10, 22], [20, 11, 16], [16, 14, 10], [18, 15, 6], [20, 11, 4]],
      rStart: 3.2, rEnd: 1.6, suctionCups: true, spines: false
    },
    // 6: Right Low Grasper (Wrapping column at X=46)
    {
      pts: [[38, 10, 22], [44, 11, 16], [48, 15, 10], [46, 16, 6], [44, 11, 4]],
      rStart: 3.2, rEnd: 1.6, suctionCups: true, spines: false
    },
    // 7: Left Rear Thrashing Coil (Deep bay)
    {
      pts: [[26, 8, 38], [18, 18, 44], [12, 28, 50], [14, 38, 56], [22, 34, 58], [26, 24, 54]],
      rStart: 4.2, rEnd: 1.5, suctionCups: true, spines: true
    },
    // 8: Right Rear Thrashing Coil (Deep bay)
    {
      pts: [[38, 8, 38], [46, 20, 44], [52, 30, 50], [50, 40, 56], [42, 36, 58], [38, 26, 54]],
      rStart: 4.2, rEnd: 1.5, suctionCups: true, spines: true
    }
  ];

  for (let i = 0; i < tentacles.length; i++) {
    const t = tentacles[i];
    drawTentacle(t.pts, t.rStart, t.rEnd, t.suctionCups, t.spines);
  }

  // 8. Churning Ocean Foam / Spray around contact points
  for (let x = 2; x < W - 2; x++) {
    for (let z = 10; z < D - 2; z++) {
      if (getVoxel(x, 8, z) !== AIR) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            const fx = x + dx;
            const fz = z + dz;
            if (fx >= 0 && fx < W && fz >= 0 && fz < D) {
              if (getVoxel(fx, 8, fz) === AIR && getVoxel(fx, 7, fz) === AIR) {
                if ((fx + fz) % 3 === 0) {
                  setVoxel(fx, 8, fz, (fx * fz) % 2 === 0 ? QUARTZ_SLAB : PRISMARINE_BRICKS);
                  setVoxel(fx, 7, fz, SEA_LANTERN);
                }
              }
            }
          }
        }
      }
    }
  }

  // 9. Ground Conformity (Rule 6)
  // For every column that has a base, extend it down to the actual terrain / seabed
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const terrainHeight = api.heightAt(x, z);
      const targetGroundY = Math.max(0, Math.min(H - 1, SEAT_Y + Math.round(terrainHeight)));

      // Find lowest occupied voxel in column
      let minY = H;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z) !== AIR) {
          minY = y;
          break;
        }
      }

      if (minY <= 14) {
        if (targetGroundY < minY) {
          for (let y = targetGroundY; y < minY; y++) {
            if (z <= 8) {
              setVoxel(x, y, z, (x + y + z) % 5 === 0 ? CRACKED_STONE_BRICKS : DEEPSLATE_BRICKS);
            } else {
              setVoxel(x, y, z, (x * z + y) % 3 === 0 ? CRYING_OBSIDIAN : DARK_PRISMARINE);
            }
          }
        }
      }
    }
  }

  // 10. BFS Connectivity Verification (Rule 9: Single 6-Connected Body)
  const visited = new Uint8Array(totalCells);
  const queue = new Int32Array(totalCells);
  let head = 0;
  let tail = 0;

  let startX = 32;
  let startY = 20;
  let startZ = 30;
  if (getVoxel(startX, startY, startZ) === AIR) {
    for (let dy = 0; dy < 15; dy++) {
      if (getVoxel(32, 12 + dy, 30) !== AIR) {
        startY = 12 + dy;
        break;
      }
    }
  }

  const startIdx = getIdx(startX, startY, startZ);
  visited[startIdx] = 1;
  queue[tail] = startIdx;
  tail++;

  const dxs = [1, -1, 0, 0, 0, 0];
  const dys = [0, 0, 1, -1, 0, 0];
  const dzs = [0, 0, 0, 0, 1, -1];

  while (head < tail) {
    const cur = queue[head];
    head++;
    const cz = Math.floor(cur / (W * H));
    const rem = cur % (W * H);
    const cy = Math.floor(rem / W);
    const cx = rem % W;

    for (let i = 0; i < 6; i++) {
      const nx = cx + dxs[i];
      const ny = cy + dys[i];
      const nz = cz + dzs[i];
      if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
        const nidx = getIdx(nx, ny, nz);
        if (!visited[nidx] && grid[nidx] !== AIR) {
          visited[nidx] = 1;
          queue[tail] = nidx;
          tail++;
        }
      }
    }
  }

  // Prune disconnected strays
  for (let i = 0; i < totalCells; i++) {
    if (grid[i] !== AIR && !visited[i]) {
      grid[i] = AIR;
    }
  }

  // 11. Material String Resolver (Theme & Rule 7 Palette)
  const stonePrimary = api.theme.stone && api.theme.stone.primary ? api.theme.stone.primary : "minecraft:smooth_quartz";
  const stoneAccent = api.theme.stone && api.theme.stone.accent ? api.theme.stone.accent : "minecraft:quartz_pillar";
  const stoneStairs = api.theme.stone && api.theme.stone.stairs ? api.theme.stone.stairs : "minecraft:quartz_stairs[facing=north,half=bottom]";
  const stoneSlab = api.theme.stone && api.theme.stone.slab ? api.theme.stone.slab : "minecraft:quartz_slab[type=bottom]";
  const plinthMat = api.theme.ground && api.theme.ground.plinth ? api.theme.ground.plinth : "minecraft:deepslate_bricks";
  const pavementMat = api.theme.ground && api.theme.ground.pavement ? api.theme.ground.pavement : "minecraft:stone_bricks";

  function resolveBlock(id, x, y, z) {
    if (id === DARK_PRISMARINE) return "minecraft:dark_prismarine";
    if (id === PRISMARINE_BRICKS) return "minecraft:prismarine_bricks";
    if (id === PRISMARINE) return "minecraft:prismarine";
    if (id === CRYING_OBSIDIAN) return "minecraft:crying_obsidian";
    if (id === SEA_LANTERN) return "minecraft:sea_lantern";
    if (id === BONE_BLOCK) return "minecraft:bone_block[axis=y]";
    if (id === SCULK) return "minecraft:sculk";
    if (id === QUARTZ_BLOCK) return stonePrimary;
    if (id === QUARTZ_PILLAR) return stoneAccent;
    if (id === DEEPSLATE_BRICKS) return plinthMat;
    if (id === FROGLIGHT) return "minecraft:ochre_froglight";
    if (id === POINTED_DRIPSTONE) return "minecraft:pointed_dripstone[thickness=tip,vertical_direction=up]";
    if (id === QUARTZ_STAIRS) return stoneStairs;
    if (id === PRISMARINE_WALL) return "minecraft:prismarine_wall";
    if (id === END_ROD) return "minecraft:end_rod[facing=north]";
    if (id === WARPED_WART) return "minecraft:warped_wart_block";
    if (id === CRACKED_STONE_BRICKS) return "minecraft:cracked_stone_bricks";
    if (id === STONE_BRICKS) return pavementMat;
    if (id === QUARTZ_SLAB) return stoneSlab;
    return "minecraft:dark_prismarine";
  }

  // 12. Emit All Blocks via api.set
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const val = getVoxel(x, y, z);
        if (val !== AIR) {
          api.set(x, y, z, resolveBlock(val, x, y, z));
        }
      }
    }
  }

  return {
    name: "leviathan_prime",
    seatY: SEAT_Y,
    anchors: {
      front: [32, 10, 0],
      maw: [32, 24, 14],
      breach: [32, 10, 6]
    }
  };
}

coastal_colossus_statue.source:
export const envelope = [25, 48, 25];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 12;
  const cz = 12;

  // Resolve palette from theme with high-classical / modern Hellenist fallbacks
  const stonePri = api.theme?.stone?.primary || "minecraft:quartz_block";
  const stoneAcc = api.theme?.stone?.accent || "minecraft:smooth_quartz";
  const stonePlinth = api.theme?.ground?.plinth || "minecraft:smooth_stone";
  const stonePave = api.theme?.ground?.pavement || "minecraft:cut_sandstone";

  const pal = {
    quartz: "minecraft:smooth_quartz",
    quartzBlock: "minecraft:quartz_block",
    quartzPillarY: "minecraft:quartz_pillar[axis=y]",
    quartzPillarX: "minecraft:quartz_pillar[axis=x]",
    quartzPillarZ: "minecraft:quartz_pillar[axis=z]",
    quartzBricks: "minecraft:quartz_bricks",
    gold: "minecraft:gold_block",
    goldTrim: "minecraft:raw_gold_block",
    copper: "minecraft:cut_copper",
    seaLantern: "minecraft:sea_lantern",
    stonePri,
    stoneAcc,
    plinth: stonePlinth,
    pavement: stonePave,
    foundation: "minecraft:stone_bricks",
    ironBars: "minecraft:iron_bars",
    chain: "minecraft:chain"
  };

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  }

  function octDist(x, z, ox = cx, oz = cz) {
    const dx = Math.abs(x - ox);
    const dz = Math.abs(z - oz);
    return Math.max(dx, dz) + 0.45 * Math.min(dx, dz);
  }

  function getStairs(dx, dz, half = "bottom") {
    let facing = "north";
    if (Math.abs(dx) > Math.abs(dz)) {
      facing = dx > 0 ? "west" : "east";
    } else {
      facing = dz > 0 ? "north" : "south";
    }
    return `minecraft:smooth_quartz_stairs[facing=${facing},half=${half}]`;
  }

  // ==========================================
  // 1. BASTION FOUNDATION & GROUND CONFORMATION
  // ==========================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = octDist(x, z);
      if (d <= 11.6) {
        const gh = api.heightAt(x, z);
        const startY = Math.min(0, gh);
        // Deep foundation down to terrain / seabed
        for (let y = startY; y <= 0; y++) {
          set(x, y, z, y < -2 ? pal.foundation : pal.plinth);
        }
      }
    }
  }

  // ==========================================
  // 2. BASTION PODIUM (Y = 0 to 13)
  // ==========================================
  // Stepped Plinth base
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = octDist(x, z);
      const dx = x - cx;
      const dz = z - cz;

      // Tier 0 (Y = 0)
      if (d <= 11.5) {
        set(x, 0, z, pal.plinth);
      }
      // Tier 1 (Y = 1)
      if (d <= 10.8) {
        if (d > 9.8) {
          set(x, 1, z, getStairs(dx, dz, "bottom"));
        } else {
          set(x, 1, z, pal.pavement);
        }
      }
      // Tier 2 (Y = 2)
      if (d <= 10.0) {
        if (d > 9.0) {
          set(x, 2, z, getStairs(dx, dz, "bottom"));
        } else {
          set(x, 2, z, pal.quartzBlock);
        }
      }
    }
  }

  // Bastion Walls & Interior Vault (Y = 3 to 10)
  for (let y = 3; y <= 10; y++) {
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const d = octDist(x, z);
        const dx = x - cx;
        const dz = z - cz;

        if (d <= 9.6) {
          const isInterior = x >= 8 && x <= 16 && z >= 8 && z <= 16 && y <= 7;
          const isSouthTunnel = x >= 11 && x <= 13 && z >= 17 && z <= 22 && y <= 5;
          const isNorthSlit = x >= 11 && x <= 13 && z >= 2 && z <= 4 && y >= 4 && y <= 6;

          if (isInterior || isSouthTunnel) {
            // Keep clear for player / interior fitting
            continue;
          }

          if (isNorthSlit) {
            if (y === 4) {
              set(x, y, z, pal.seaLantern);
            } else {
              set(x, y, z, pal.ironBars);
            }
            continue;
          }

          // Corner pilasters
          const isCorner = (Math.abs(dx) >= 6 && Math.abs(dz) >= 6) || Math.abs(dx) === 9 || Math.abs(dz) === 9;
          if (isCorner) {
            set(x, y, z, pal.quartzPillarY);
          } else if (d >= 7.8) {
            // Masonry wall
            if (y === 3 || y === 10) {
              set(x, y, z, pal.quartzBricks);
            } else {
              set(x, y, z, (x + y + z) % 4 === 0 ? pal.stonePri : pal.quartz);
            }
          } else if (y >= 8) {
            // Groin vault ceiling of interior
            set(x, y, z, pal.quartz);
          }
        }
      }
    }
  }

  // South Grand Portal Portico (Z = 20..22)
  for (let y = 1; y <= 6; y++) {
    set(10, y, 22, pal.quartzPillarY);
    set(14, y, 22, pal.quartzPillarY);
    if (y === 1) {
      set(10, y, 22, pal.gold);
      set(14, y, 22, pal.gold);
    }
    if (y === 6) {
      for (let x = 10; x <= 14; x++) {
        set(x, y, 22, pal.gold);
      }
      set(12, 7, 22, pal.quartz);
    }
  }

  // Bastion Entablature & Cornice (Y = 11 to 12)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = octDist(x, z);
      const dx = x - cx;
      const dz = z - cz;

      // Y = 11: Cantilevered inverted stairs
      if (d <= 10.4 && d > 8.8) {
        set(x, 11, z, getStairs(dx, dz, "top"));
      } else if (d <= 8.8) {
        set(x, 11, z, pal.quartzBlock);
      }

      // Y = 12: Frieze with gold metopes & triglyphs
      if (d <= 9.8) {
        if (d > 8.6) {
          const triglyph = (Math.abs(dx) + Math.abs(dz)) % 2 === 0;
          set(x, 12, z, triglyph ? pal.gold : pal.quartzBricks);
        } else {
          set(x, 12, z, pal.quartzBlock);
        }
      }
    }
  }

  // Promenade Deck & Parapet (Y = 13 to 14)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = octDist(x, z);
      const dx = x - cx;
      const dz = z - cz;

      // Deck floor
      if (d <= 9.2) {
        set(x, 13, z, ((dx * dx + dz * dz) % 3 === 0) ? pal.stoneAcc : pal.quartz);
      }

      // Parapet perimeter
      if (d <= 9.6 && d > 8.4) {
        set(x, 14, z, "minecraft:smooth_quartz_slab[type=bottom]");
      }
    }
  }

  // 4 Corner Braziers / Sea Beacons overlooking the waters
  const beaconCorners = [
    [5, 5], [19, 5], [5, 19], [19, 19]
  ];
  for (const [bx, bz] of beaconCorners) {
    set(bx, 14, bz, pal.gold);
    set(bx, 15, bz, pal.seaLantern);
    set(bx, 16, bz, "minecraft:smooth_quartz_slab[type=bottom]");
  }

  // ==========================================
  // 3. STATUE PLINTH (Y = 13 to 15)
  // ==========================================
  for (let x = 9; x <= 15; x++) {
    for (let z = 9; z <= 15; z++) {
      const edge = x === 9 || x === 15 || z === 9 || z === 15;
      if (edge) {
        set(x, 14, z, getStairs(x - cx, z - cz, "bottom"));
      } else {
        set(x, 14, z, pal.gold);
      }
    }
  }
  for (let x = 10; x <= 14; x++) {
    for (let z = 10; z <= 14; z++) {
      const edge = x === 10 || x === 14 || z === 10 || z === 14;
      set(x, 15, z, edge ? pal.quartzBricks : pal.gold);
    }
  }

  // ==========================================
  // 4. ATHENA COLOSSUS SCULPTURE
  // ==========================================

  // A. Robe / Peplos (Y = 15 to 24)
  for (let y = 15; y <= 24; y++) {
    const t = (y - 15) / 9;
    const baseR = 3.3 - t * 1.1;
    // Classical contrapposto stance shift
    const scx = cx + Math.sin(t * Math.PI) * 0.4;
    const scz = cz - 0.2 + t * 0.4;

    for (let x = 8; x <= 16; x++) {
      for (let z = 8; z <= 16; z++) {
        const dx = x - scx;
        const dz = z - scz;
        const dist = Math.hypot(dx, dz);
        const angle = Math.atan2(dz, dx);
        // Fluted drapery folds
        const flutedR = baseR * (1.0 + 0.12 * Math.cos(8 * angle));

        if (dist <= flutedR) {
          if (y === 15) {
            set(x, y, z, dist > flutedR - 0.8 ? pal.gold : pal.quartz);
          } else if (dist > flutedR - 0.6) {
            set(x, y, z, pal.quartz);
          } else {
            set(x, y, z, pal.stonePri);
          }
        }
      }
    }
  }

  // Forward Left Sandal peeking from hem
  set(10, 15, 8, pal.gold);
  set(10, 15, 9, pal.copper);

  // B. Golden Belt / Cincture (Y = 25)
  for (let x = 10; x <= 14; x++) {
    for (let z = 10; z <= 14; z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist <= 2.2) {
        set(x, 25, z, dist >= 1.4 ? pal.gold : pal.quartz);
      }
    }
  }
  // Belt Medallion & Hanging Knot
  set(12, 25, 9, pal.copper);
  set(12, 24, 9, pal.gold);
  set(12, 23, 9, "minecraft:smooth_quartz_slab[type=top]");

  // C. Torso & Aegis Cuirass (Y = 26 to 31)
  for (let y = 26; y <= 31; y++) {
    for (let x = 9; x <= 15; x++) {
      for (let z = 9; z <= 14; z++) {
        const dx = (x - cx) / 2.6;
        const dz = (z - (cz - 0.2)) / 1.9;
        if (dx * dx + dz * dz <= 1.0) {
          set(x, y, z, pal.quartz);
        }
      }
    }
  }

  // Golden Gorgoneion on chest (Z = 9, Y = 28..29)
  set(12, 28, 9, pal.seaLantern); // Radiant heart of aegis
  set(11, 28, 9, pal.gold);
  set(13, 28, 9, pal.gold);
  set(12, 29, 9, pal.goldTrim);
  set(12, 27, 9, pal.gold);

  // Shoulders (Y = 30 to 31)
  for (let x = 8; x <= 16; x++) {
    for (let z = 10; z <= 13; z++) {
      if (Math.abs(x - cx) <= 4.2 && Math.abs(z - cz) <= 1.5) {
        set(x, 31, z, pal.quartz);
        // Golden epaulets / serpent trim
        if (Math.abs(x - cx) >= 3.0) {
          set(x, 32, z, "minecraft:smooth_quartz_slab[type=bottom]");
          set(x, 31, z, pal.gold);
        }
      }
    }
  }

  // D. Left Arm & Great Aspis Shield (Defending NW/Sea)
  // Left arm structure
  set(8, 30, 11, pal.quartz);
  set(8, 29, 11, pal.quartz);
  set(7, 28, 10, pal.quartz);
  set(7, 27, 10, pal.quartz);
  set(7, 26, 9, pal.quartz);
  set(6, 25, 8, pal.quartz); // Bracing shield grip

  // Aspis Shield (Convex circular hoplite shield centered at (5, 24, 7))
  const shieldCenter = [5, 24, 7];
  for (let dy = -3; dy <= 3; dy++) {
    for (let du = -3; du <= 3; du++) {
      const sr = Math.hypot(du, dy);
      if (sr <= 3.4) {
        const curvature = Math.round((3.4 - sr) * 0.4);
        const sx = shieldCenter[0] + Math.round(du * 0.7) - curvature;
        const sz = shieldCenter[1] - Math.round(du * 0.7) - curvature;
        const sy = shieldCenter[1] + dy;

        let mat = pal.quartz;
        if (sr >= 2.5) {
          mat = pal.gold; // Gilded rim
        } else if (sr <= 1.0) {
          mat = (du === 0 && dy === 0) ? pal.seaLantern : pal.goldTrim; // Boss
        }
        set(sx, sy, sz, mat);
        // Interior backing
        set(sx + 1, sy, sz, pal.quartz);
      }
    }
  }

  // E. Right Arm & Raised Gilded Spear of Athena (Dory)
  // Right Arm raised high
  set(16, 31, 11, pal.quartz);
  set(16, 32, 12, pal.quartz);
  set(17, 33, 12, pal.quartz);
  set(17, 34, 11, pal.quartz);
  set(16, 35, 10, pal.gold); // Golden gauntlet gripping spear

  // Spear trajectory: from butt (18, 25, 17) through hand (16, 35, 10) to spearhead (13, 47, 2)
  const pButt = [18, 25, 17];
  const pTip = [13, 47, 2];
  const steps = 60;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const px = Math.round(pButt[0] + t * (pTip[0] - pButt[0]));
    const py = Math.round(pButt[1] + t * (pTip[1] - pButt[1]));
    const pz = Math.round(pButt[2] + t * (pTip[2] - pButt[2]));

    if (py >= 44) {
      // Spearhead blade
      set(px, py, pz, pal.gold);
      if (py === 45) {
        set(px, py, pz, pal.seaLantern);
        set(px + 1, py, pz, "minecraft:smooth_quartz_slab[type=bottom]");
        set(px, py, pz + 1, "minecraft:smooth_quartz_slab[type=bottom]");
      }
    } else if (py <= 26) {
      // Sauroter (butt-spike)
      set(px, py, pz, pal.copper);
    } else {
      // Spear shaft
      set(px, py, pz, py % 3 === 0 ? pal.gold : pal.quartz);
    }
  }

  // F. Neck, Face & Hair (Y = 32 to 37)
  // Neck
  set(12, 32, 11, pal.quartz);
  set(12, 33, 11, pal.quartz);
  set(11, 32, 11, pal.quartz);
  set(13, 32, 11, pal.quartz);

  // Flowing Hair tresses cascading down back
  for (let y = 29; y <= 34; y++) {
    set(10, y, 13, pal.quartz);
    set(14, y, 13, pal.quartz);
    set(11, y, 13, pal.stonePri);
    set(12, y, 13, pal.stonePri);
    set(13, y, 13, pal.stonePri);
  }

  // Head volume & Serene Classical Face (Y = 34 to 37)
  for (let y = 34; y <= 37; y++) {
    for (let x = 10; x <= 14; x++) {
      for (let z = 9; z <= 13; z++) {
        const dx = (x - cx) / 2.0;
        const dz = (z - 11) / 1.8;
        if (dx * dx + dz * dz <= 1.0) {
          set(x, y, z, pal.quartz);
        }
      }
    }
  }

  // Facial Profile (Looking resolutely North toward the sea monsters)
  set(12, 34, 9, pal.quartz); // Chin
  set(12, 35, 8, "minecraft:smooth_quartz_stairs[facing=north,half=bottom]"); // Nose
  set(11, 35, 9, pal.quartz); // Left cheek
  set(13, 35, 9, pal.quartz); // Right cheek
  set(12, 36, 9, pal.quartz); // Forehead

  // G. Attic / Corinthian Helmet & Majestic Plume (Y = 36 to 44)
  // Cheek guards
  set(10, 34, 9, pal.gold);
  set(10, 35, 9, pal.quartz);
  set(14, 34, 9, pal.gold);
  set(14, 35, 9, pal.quartz);

  // Golden Diadem / Brow Band (Y = 36)
  for (let x = 10; x <= 14; x++) {
    set(x, 36, 8, pal.gold);
  }
  set(10, 36, 9, pal.gold);
  set(14, 36, 9, pal.gold);

  // Helmet Dome (Y = 37..38)
  for (let x = 10; x <= 14; x++) {
    for (let z = 9; z <= 13; z++) {
      if (Math.hypot(x - cx, z - 11) <= 2.2) {
        set(x, 37, z, pal.gold);
        set(x, 38, z, pal.quartz);
      }
    }
  }

  // High Horsehair Plume Crest (Y = 38 to 44)
  const plumeArc = [
    { y: 38, z: 8, h: 1 },
    { y: 39, z: 8, h: 2 },
    { y: 40, z: 9, h: 2 },
    { y: 41, z: 10, h: 2 },
    { y: 42, z: 11, h: 2 },
    { y: 43, z: 12, h: 2 }, // Apex of Crest
    { y: 44, z: 12, h: 1 },
    { y: 43, z: 13, h: 1 },
    { y: 42, z: 14, h: 1 },
    { y: 40, z: 15, h: 1 },
    { y: 38, z: 15, h: 1 },
    { y: 36, z: 15, h: 1 }  // Trailing plume tail
  ];

  for (const node of plumeArc) {
    for (let dh = 0; dh < node.h; dh++) {
      const py = node.y + dh;
      set(cx, py, node.z, pal.gold);
      // Crest thickness and fluting
      set(cx - 1, py, node.z, "minecraft:smooth_quartz_slab[type=bottom]");
      set(cx + 1, py, node.z, "minecraft:smooth_quartz_slab[type=bottom]");
    }
  }

  return {
    name: "coastal_colossus_statue",
    seatY: 0,
    anchors: {
      front: [cx, 0, 0],
      door: [cx, 1, 23]
    },
    interiors: [
      {
        min: [8, 1, 8],
        max: [16, 7, 16],
        kind: "vault"
      }
    ]
  };
}

sea_monster_spawn.source:
export const envelope = [16, 20, 16];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;
  const rnd = api.random;
  const instIdx = api.instance.index;

  // 3D Grid buffer: 16 x 20 x 16
  const grid = new Array(W * H * D).fill(null);

  function getIdx(x, y, z) {
    return x + y * W + z * (W * H);
  }

  function setVoxel(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[getIdx(ix, iy, iz)] = block;
    }
  }

  function getVoxel(x, y, z) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[getIdx(ix, iy, iz)];
    }
    return null;
  }

  function fillEllipsoid(cx, cy, cz, rx, ry, rz, blockFunc) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      const dx = rx > 0 ? (x - cx) / rx : 0;
      const dx2 = dx * dx;
      if (dx2 > 1.05) continue;
      for (let y = minY; y <= maxY; y++) {
        const dy = ry > 0 ? (y - cy) / ry : 0;
        const dy2 = dy * dy;
        if (dx2 + dy2 > 1.05) continue;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = rz > 0 ? (z - cz) / rz : 0;
          const d2 = dx2 + dy2 + dz * dz;
          if (d2 <= 1.0) {
            const block = blockFunc(x, y, z, Math.sqrt(d2), dx, dy, dz);
            if (block) {
              setVoxel(x, y, z, block);
            }
          }
        }
      }
    }
  }

  function catmullRom(p0, p1, p2, p3, t) {
    const t2 = t * t;
    const t3 = t2 * t;
    return 0.5 * (
      (2 * p1) +
      (-p0 + p2) * t +
      (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
      (-p0 + 3 * p1 - 3 * p2 + p3) * t3
    );
  }

  function drawSpline(points, stepsPerSeg, blockFunc) {
    if (points.length < 2) return;
    const pts = [
      {
        x: 2 * points[0].x - points[1].x,
        y: 2 * points[0].y - points[1].y,
        z: 2 * points[0].z - points[1].z,
        r: points[0].r
      },
      ...points,
      {
        x: 2 * points[points.length - 1].x - points[points.length - 2].x,
        y: 2 * points[points.length - 1].y - points[points.length - 2].y,
        z: 2 * points[points.length - 1].z - points[points.length - 2].z,
        r: points[points.length - 1].r
      }
    ];

    const numSegs = pts.length - 3;
    for (let seg = 0; seg < numSegs; seg++) {
      const p0 = pts[seg];
      const p1 = pts[seg + 1];
      const p2 = pts[seg + 2];
      const p3 = pts[seg + 3];

      for (let s = 0; s <= stepsPerSeg; s++) {
        const t = s / stepsPerSeg;
        const cx = catmullRom(p0.x, p1.x, p2.x, p3.x, t);
        const cy = catmullRom(p0.y, p1.y, p2.y, p3.y, t);
        const cz = catmullRom(p0.z, p1.z, p2.z, p3.z, t);
        const cr = catmullRom(p0.r, p1.r, p2.r, p3.r, t);
        const globalT = (seg + t) / numSegs;

        fillEllipsoid(cx, cy, cz, cr, cr, cr, (x, y, z, d, dx, dy, dz) => {
          return blockFunc(x, y, z, d, dx, dy, dz, globalT, cx, cy, cz);
        });
      }
    }
  }

  // Procedural scale texture generator
  function getScaleBlock(x, y, z, dy, isVentralGlow) {
    if (dy < -0.55) {
      if (isVentralGlow) return "minecraft:sea_lantern";
      return (Math.floor(x + z) % 2 === 0) ? "minecraft:prismarine_bricks" : "minecraft:dark_prismarine";
    }
    if (dy > 0.55) {
      return (Math.floor(x * 2 + z) % 3 === 0) ? "minecraft:deepslate_tiles" : "minecraft:dark_prismarine";
    }
    const hash = Math.abs(Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453) % 1;
    if (hash > 0.65) return "minecraft:prismarine_bricks";
    if (hash > 0.25) return "minecraft:dark_prismarine";
    return "minecraft:prismarine";
  }

  // 3 Archetypes of aquatic horrors
  const archetype = instIdx % 3;
  let headPos = [7.5, seatY + 11, 1.0];
  let monsterName = "Breaching Sea Serpent";

  if (archetype === 0) {
    // ==========================================
    // ARCHETYPE 0: THE GREAT HORNED SEA WYRM
    // ==========================================
    monsterName = "Breaching Sea Wyrm";
    const coilSide = (instIdx % 2 === 0) ? 1 : -1;
    const archHeight = 9.5 + rnd() * 3.5;
    const headY = seatY + 9.5 + rnd() * 2.5;
    const headX = 7.5 + (rnd() - 0.5) * 2.5;
    headPos = [headX, headY, 1.0];

    const eyeGlow = (instIdx % 4 === 0) ? "minecraft:magma_block" : "minecraft:sea_lantern";
    const hornStyle = instIdx % 3;

    // Main Arch Body Spline
    const wyrmPoints = [
      { x: headX + coilSide * 3.8, y: seatY + 0.0, z: 13.5, r: 2.2 },
      { x: headX + coilSide * 3.2, y: seatY + 2.5, z: 11.5, r: 2.4 },
      { x: headX + coilSide * 1.5, y: seatY + archHeight, z: 8.5, r: 2.3 },
      { x: headX - coilSide * 1.8, y: seatY + 4.5, z: 5.5, r: 2.0 },
      { x: headX - coilSide * 0.5, y: headY - 1.2, z: 3.5, r: 1.9 },
      { x: headX, y: headY, z: 2.0, r: 2.0 },
      { x: headX, y: headY - 0.3, z: 0.8, r: 1.2 }
    ];

    drawSpline(wyrmPoints, 16, (x, y, z, d, dx, dy, dz, t, cx, cy, cz) => {
      const isGlow = (Math.floor(cz + cy) % 3 === 0);
      return getScaleBlock(x, y, z, dy, isGlow);
    });

    // Dorsal Spines along main arch
    for (let z = 6; z <= 11; z++) {
      for (let x = 1; x < W - 1; x++) {
        for (let y = H - 2; y >= seatY + 5; y--) {
          if (getVoxel(x, y, z) && !getVoxel(x, y + 1, z)) {
            if ((x + z) % 2 === 0) {
              setVoxel(x, y + 1, z, "minecraft:deepslate_tile_wall");
              if (y + 2 < H && (z === 8 || z === 9)) {
                setVoxel(x, y + 2, z, "minecraft:prismarine_wall");
              }
            } else {
              setVoxel(x, y + 1, z, "minecraft:dark_prismarine_stairs[facing=south,half=bottom]");
            }
            break;
          }
        }
      }
    }

    // Head Sculpting: Upper Skull & Lower Jaw
    const hx = Math.round(headX);
    const hy = Math.round(headY);

    // Upper Jaw
    fillEllipsoid(hx, hy + 0.3, 1.2, 1.8, 1.0, 1.5, (x, y, z, d, dx, dy, dz) => {
      if (dy > 0.3) return "minecraft:deepslate_tiles";
      return "minecraft:dark_prismarine";
    });

    // Lower Jaw (gaping open downward)
    fillEllipsoid(hx, hy - 1.6, 1.5, 1.4, 0.8, 1.3, (x, y, z, d, dx, dy, dz) => {
      if (dy < -0.3) return "minecraft:dark_prismarine";
      return "minecraft:prismarine_bricks";
    });

    // Mouth Cavity / Throat
    setVoxel(hx, hy - 0.6, 1.8, "minecraft:crying_obsidian");
    setVoxel(hx, hy - 0.6, 2.2, "minecraft:crying_obsidian");

    // Teeth / Fangs
    setVoxel(hx - 1, hy - 0.5, 0.8, "minecraft:pointed_dripstone[thickness=tip,vertical_direction=down]");
    setVoxel(hx + 1, hy - 0.5, 0.8, "minecraft:pointed_dripstone[thickness=tip,vertical_direction=down]");
    setVoxel(hx - 1, hy - 1.1, 1.0, "minecraft:bone_block");
    setVoxel(hx + 1, hy - 1.1, 1.0, "minecraft:bone_block");

    // Eyes on side of skull
    setVoxel(hx - 2, hy + 0.4, 1.8, eyeGlow);
    setVoxel(hx + 2, hy + 0.4, 1.8, eyeGlow);
    setVoxel(hx - 2, hy + 1.2, 1.8, "minecraft:deepslate_tiles");
    setVoxel(hx + 2, hy + 1.2, 1.8, "minecraft:deepslate_tiles");

    // Horns / Frills
    if (hornStyle === 0) {
      // Swept Dragon Horns
      const leftHorn = [
        { x: hx - 1.2, y: hy + 1.0, z: 2.2, r: 0.7 },
        { x: hx - 2.2, y: hy + 2.2, z: 3.5, r: 0.6 },
        { x: hx - 2.8, y: hy + 3.4, z: 5.0, r: 0.4 }
      ];
      const rightHorn = [
        { x: hx + 1.2, y: hy + 1.0, z: 2.2, r: 0.7 },
        { x: hx + 2.2, y: hy + 2.2, z: 3.5, r: 0.6 },
        { x: hx + 2.8, y: hy + 3.4, z: 5.0, r: 0.4 }
      ];
      drawSpline(leftHorn, 6, () => "minecraft:bone_block");
      drawSpline(rightHorn, 6, () => "minecraft:bone_block");
    } else if (hornStyle === 1) {
      // High Trident Crest
      for (let cy = hy + 1; cy <= hy + 3 && cy < H; cy++) {
        setVoxel(hx, cy, 2.2, "minecraft:deepslate_tile_wall");
        setVoxel(hx, cy, 3.0, "minecraft:prismarine_wall");
        if (cy <= hy + 2) {
          setVoxel(hx - 1, cy, 2.5, "minecraft:prismarine_wall");
          setVoxel(hx + 1, cy, 2.5, "minecraft:prismarine_wall");
        }
      }
    } else {
      // Abyssal Curved Crest
      const leftHorn = [
        { x: hx - 1.0, y: hy + 1.2, z: 2.0, r: 0.7 },
        { x: hx - 2.4, y: hy + 2.5, z: 2.2, r: 0.6 },
        { x: hx - 3.2, y: hy + 1.8, z: 1.2, r: 0.4 }
      ];
      const rightHorn = [
        { x: hx + 1.0, y: hy + 1.2, z: 2.0, r: 0.7 },
        { x: hx + 2.4, y: hy + 2.5, z: 2.2, r: 0.6 },
        { x: hx + 3.2, y: hy + 1.8, z: 1.2, r: 0.4 }
      ];
      drawSpline(leftHorn, 6, () => "minecraft:polished_blackstone");
      drawSpline(rightHorn, 6, () => "minecraft:polished_blackstone");
    }

    // Secondary Breaching Tail / Loop
    const tailPoints = [
      { x: hx - coilSide * 3.8, y: seatY + 0.0, z: 10.5, r: 1.7 },
      { x: hx - coilSide * 4.4, y: seatY + 4.8, z: 12.5, r: 1.8 },
      { x: hx - coilSide * 3.2, y: seatY + 2.8, z: 14.5, r: 1.4 },
      { x: hx - coilSide * 2.2, y: seatY + 0.0, z: 15.0, r: 1.1 }
    ];
    drawSpline(tailPoints, 12, (x, y, z, d, dx, dy, dz) => {
      return getScaleBlock(x, y, z, dy, false);
    });

  } else if (archetype === 1) {
    // ==========================================
    // ARCHETYPE 1: KRAKEN / CEPHALOPOD HORROR
    // ==========================================
    monsterName = "Abyssal Kraken Horror";
    const mantleX = 7.5 + (rnd() - 0.5) * 1.8;
    const mantleZ = 8.5 + (rnd() - 0.5) * 1.5;
    const mantleRadX = 2.6 + rnd() * 0.5;
    const mantleRadY = 3.8 + rnd() * 0.7;
    const whip = (instIdx % 2 === 0) ? 1 : -1;
    headPos = [mantleX, seatY + 11.5, 1.0];

    // Central Bulbous Mantle
    fillEllipsoid(mantleX, seatY + 5.5, mantleZ, mantleRadX, mantleRadY, 2.7, (x, y, z, d, dx, dy, dz) => {
      if (dy > 0.4) return (Math.floor(x + z) % 2 === 0) ? "minecraft:deepslate_tiles" : "minecraft:dark_prismarine";
      if (dy < -0.4 && dz < -0.3) return "minecraft:sea_lantern";
      return getScaleBlock(x, y, z, dy, false);
    });

    // Mantle Apex Spikes
    const mx = Math.round(mantleX);
    const mz = Math.round(mantleZ);
    const myTop = Math.min(H - 2, Math.round(seatY + 5.5 + mantleRadY));
    setVoxel(mx, myTop + 1, mz, "minecraft:deepslate_tile_wall");
    setVoxel(mx, myTop + 2, mz, "minecraft:prismarine_wall");
    setVoxel(mx - 1, myTop, mz, "minecraft:dark_prismarine_stairs[facing=east,half=bottom]");
    setVoxel(mx + 1, myTop, mz, "minecraft:dark_prismarine_stairs[facing=west,half=bottom]");

    // Abyssal Maw / Beak
    const beakY = Math.round(seatY + 3.8);
    const beakZ = Math.round(mantleZ - 2.5);
    setVoxel(mx, beakY, beakZ, "minecraft:blackstone");
    setVoxel(mx - 1, beakY, beakZ, "minecraft:bone_block");
    setVoxel(mx + 1, beakY, beakZ, "minecraft:bone_block");
    setVoxel(mx, beakY + 1, beakZ, "minecraft:bone_block");
    setVoxel(mx, beakY - 1, beakZ, "minecraft:bone_block");

    // Glowing Eye Cluster
    const eyeMat = (instIdx % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:shroomlight";
    setVoxel(mx - 2, beakY + 1, beakZ + 1, eyeMat);
    setVoxel(mx + 2, beakY + 1, beakZ + 1, eyeMat);
    setVoxel(mx - 1, beakY + 2, beakZ + 1, eyeMat);
    setVoxel(mx + 1, beakY + 2, beakZ + 1, eyeMat);

    // Tentacle 1: Left Breaching Strike
    const t1 = [
      { x: mantleX - 1.8, y: seatY + 3.0, z: mantleZ - 1.2, r: 1.7 },
      { x: mantleX - 4.2 * whip, y: seatY + 6.5, z: 5.5, r: 1.5 },
      { x: mantleX - 5.2 * whip, y: seatY + 11.5, z: 3.2, r: 1.2 },
      { x: mantleX - 3.8 * whip, y: seatY + 14.5, z: 1.2, r: 0.9 },
      { x: mantleX - 1.8 * whip, y: seatY + 13.5, z: 0.4, r: 0.6 }
    ];

    // Tentacle 2: Right Breaching Strike
    const t2 = [
      { x: mantleX + 1.8, y: seatY + 3.0, z: mantleZ - 1.2, r: 1.7 },
      { x: mantleX + 4.2 * whip, y: seatY + 6.0, z: 4.8, r: 1.5 },
      { x: mantleX + 5.2 * whip, y: seatY + 11.0, z: 2.2, r: 1.2 },
      { x: mantleX + 3.2 * whip, y: seatY + 14.0, z: 0.8, r: 0.9 },
      { x: mantleX + 1.2 * whip, y: seatY + 12.0, z: 0.2, r: 0.6 }
    ];

    // Tentacle 3: High Overhead Whip
    const t3 = [
      { x: mantleX, y: seatY + 5.5, z: mantleZ + 1.8, r: 1.7 },
      { x: mantleX + 1.5 * whip, y: seatY + 9.5, z: mantleZ + 2.2, r: 1.4 },
      { x: mantleX, y: seatY + 15.0, z: mantleZ + 0.2, r: 1.2 },
      { x: mantleX - 1.5 * whip, y: seatY + 14.0, z: 4.2, r: 0.9 },
      { x: mantleX - 0.5 * whip, y: seatY + 11.5, z: 2.2, r: 0.6 }
    ];

    // Tentacle 4: Low Coastal Grasp
    const t4 = [
      { x: mantleX - 1.5, y: seatY + 2.0, z: mantleZ - 1.8, r: 1.5 },
      { x: mantleX - 3.2, y: seatY + 2.8, z: 4.0, r: 1.3 },
      { x: mantleX - 0.8, y: seatY + 3.6, z: 1.8, r: 1.0 },
      { x: mantleX + 1.8, y: seatY + 4.5, z: 0.4, r: 0.7 }
    ];

    function drawTentacle(pts) {
      drawSpline(pts, 14, (x, y, z, d, dx, dy, dz, t, cx, cy, cz) => {
        // Inner curve has suction pads
        if (dy < -0.35 && (Math.floor(x + y + z) % 3 === 0)) {
          return "minecraft:sea_lantern";
        }
        if (dy > 0.4) return "minecraft:dark_prismarine";
        return (Math.floor(x + z) % 2 === 0) ? "minecraft:prismarine_bricks" : "minecraft:prismarine";
      });
    }

    drawTentacle(t1);
    drawTentacle(t2);
    drawTentacle(t3);
    drawTentacle(t4);

  } else {
    // ==========================================
    // ARCHETYPE 2: ARMORED CARAPACE LEVIATHAN
    // ==========================================
    monsterName = "Armored Leviathan Behemoth";
    const bodyTilt = (instIdx % 2 === 0) ? 1 : -1;
    const crestPeak = seatY + 9.5 + rnd() * 2.5;
    const lx = 7.5;
    const headY = seatY + 10.5 + rnd() * 2.0;
    headPos = [lx, headY, 0.8];

    // Sinuous Heavy Body Spline
    const leviathanPoints = [
      { x: lx + bodyTilt * 3.5, y: seatY + 0.0, z: 13.5, r: 2.6 },
      { x: lx + bodyTilt * 2.4, y: seatY + 3.2, z: 11.5, r: 2.7 },
      { x: lx - bodyTilt * 0.4, y: crestPeak, z: 7.5, r: 2.6 },
      { x: lx - bodyTilt * 1.2, y: seatY + 8.5, z: 4.5, r: 2.3 },
      { x: lx, y: headY, z: 2.2, r: 2.2 },
      { x: lx, y: headY - 0.5, z: 0.6, r: 1.4 }
    ];

    drawSpline(leviathanPoints, 16, (x, y, z, d, dx, dy, dz, t, cx, cy, cz) => {
      if (dy > 0.3) {
        // Heavy dorsal carapace armor
        if ((Math.floor(cz) % 2 === 0) && dy > 0.6) return "minecraft:deepslate_tiles";
        if (Math.abs(dx) < 0.25 && dy > 0.7) return "minecraft:crying_obsidian";
        return "minecraft:blackstone";
      }
      if (dy < -0.5) {
        return (Math.floor(cz) % 3 === 0) ? "minecraft:sea_lantern" : "minecraft:prismarine_bricks";
      }
      return (Math.floor(x * 2 + y) % 3 === 0) ? "minecraft:dark_prismarine" : "minecraft:prismarine";
    });

    // Pectoral Flippers / Fins
    const leftFlipper = [
      { x: lx - 2.0, y: seatY + 3.2, z: 7.5, r: 1.4 },
      { x: lx - 4.5, y: seatY + 2.8, z: 6.8, r: 1.1 },
      { x: lx - 6.2, y: seatY + 2.2, z: 8.2, r: 0.7 }
    ];
    const rightFlipper = [
      { x: lx + 2.0, y: seatY + 3.2, z: 7.5, r: 1.4 },
      { x: lx + 4.5, y: seatY + 2.8, z: 6.8, r: 1.1 },
      { x: lx + 6.2, y: seatY + 2.2, z: 8.2, r: 0.7 }
    ];
    drawSpline(leftFlipper, 8, () => "minecraft:dark_prismarine_slab[type=bottom]");
    drawSpline(rightFlipper, 8, () => "minecraft:dark_prismarine_slab[type=bottom]");

    // Armored Head & Mandibles
    const hx = Math.round(lx);
    const hy = Math.round(headY);

    // Brow & Crown
    fillEllipsoid(hx, hy + 0.6, 1.4, 1.8, 1.1, 1.6, (x, y, z, d, dx, dy, dz) => {
      if (dy > 0.3) return "minecraft:deepslate_tiles";
      return "minecraft:dark_prismarine";
    });

    // Lower Armored Chin
    fillEllipsoid(hx, hy - 1.4, 1.6, 1.5, 0.8, 1.4, () => "minecraft:blackstone");

    // Lateral Mandibles / Tusks
    setVoxel(hx - 2, hy - 0.4, 0.6, "minecraft:bone_block");
    setVoxel(hx + 2, hy - 0.4, 0.6, "minecraft:bone_block");
    setVoxel(hx - 2, hy - 0.4, 0.0, "minecraft:pointed_dripstone[thickness=tip,vertical_direction=up]");
    setVoxel(hx + 2, hy - 0.4, 0.0, "minecraft:pointed_dripstone[thickness=tip,vertical_direction=up]");

    // Glowing Eyes
    setVoxel(hx - 2, hy + 0.5, 1.6, "minecraft:magma_block");
    setVoxel(hx + 2, hy + 0.5, 1.6, "minecraft:magma_block");

    // Bioluminescent Barbels under Chin
    setVoxel(hx - 1, hy - 2.2, 1.2, "minecraft:prismarine_wall");
    setVoxel(hx + 1, hy - 2.2, 1.2, "minecraft:prismarine_wall");
    setVoxel(hx - 1, hy - 3.0, 1.2, "minecraft:sea_lantern");
    setVoxel(hx + 1, hy - 3.0, 1.2, "minecraft:sea_lantern");

    // Dorsal Carapace Spines along ridge
    for (let z = 5; z <= 10; z++) {
      for (let x = 2; x < W - 2; x++) {
        for (let y = H - 2; y >= seatY + 4; y--) {
          if (getVoxel(x, y, z) && !getVoxel(x, y + 1, z)) {
            setVoxel(x, y + 1, z, "minecraft:deepslate_tile_wall");
            if (y + 2 < H && z === 7) {
              setVoxel(x, y + 2, z, "minecraft:deepslate_tile_wall");
            }
            break;
          }
        }
      }
    }
  }

  // ==========================================
  // TERRAIN CONFORMANCE & SEATING (RULES 5 & 6)
  // ==========================================
  // Extend all submerged breach columns down to actual seabed/ground
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const terrainHeight = seatY + Math.round(api.heightAt(x, z));
      const groundTarget = Math.max(0, Math.min(seatY + 4, terrainHeight));

      // Find lowest solid voxel in this column
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z)) {
          minY = y;
          break;
        }
      }

      if (minY !== -1 && minY <= seatY + 3) {
        if (groundTarget < minY) {
          for (let y = minY - 1; y >= groundTarget; y--) {
            setVoxel(x, y, z, "minecraft:dark_prismarine");
          }
        } else if (groundTarget > minY) {
          for (let y = minY; y <= groundTarget; y++) {
            setVoxel(x, y, z, "minecraft:dark_prismarine");
          }
        }
      }
    }
  }

  // ==========================================
  // 6-CONNECTED COMPONENT FILTER (RULE 9)
  // ==========================================
  const visited = new Uint8Array(W * H * D);
  let maxComp = [];

  for (let idx = 0; idx < W * H * D; idx++) {
    if (!grid[idx] || visited[idx]) continue;

    const comp = [idx];
    visited[idx] = 1;
    let head = 0;
    while (head < comp.length) {
      const cur = comp[head++];
      const cx = cur % W;
      const cy = Math.floor(cur / W) % H;
      const cz = Math.floor(cur / (W * H));

      const neighbors = [
        [cx + 1, cy, cz], [cx - 1, cy, cz],
        [cx, cy + 1, cz], [cx, cy - 1, cz],
        [cx, cy, cz + 1], [cx, cy, cz - 1]
      ];
      for (const [nx, ny, nz] of neighbors) {
        if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
          const nidx = getIdx(nx, ny, nz);
          if (grid[nidx] && !visited[nidx]) {
            visited[nidx] = 1;
            comp.push(nidx);
          }
        }
      }
    }

    if (comp.length > maxComp.length) {
      maxComp = comp;
    }
  }

  // Clear any disconnected floaters
  const mainSet = new Set(maxComp);
  for (let idx = 0; idx < W * H * D; idx++) {
    if (grid[idx] && !mainSet.has(idx)) {
      grid[idx] = null;
    }
  }

  // Emit all voxels to the world
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = getVoxel(x, y, z);
        if (blk) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  const frontX = Math.max(1, Math.min(W - 2, Math.floor(headPos[0])));
  const frontY = Math.max(seatY, Math.min(H - 2, Math.floor(headPos[1])));

  return {
    name: monsterName,
    seatY: seatY,
    anchors: {
      front: [frontX, frontY, 0]
    }
  };
}
